@@ -55,3 +55,25 @@ export function waste(store, batchId, qty, { at, ref = "" }) {
   batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
   return record(store, { type: "waste", batchId, qty, at, ref });
 }
+
+/** Moves a whole batch or splits off stock at another location. */
+export function transfer(store, batchId, to, qty, { at }) {
+  const batch = getBatch(store, batchId);
+  if (!store.data.locations.some((location) => location.id === to))
+    throw new AppError("unknown_location", { id: to });
+  if (typeof qty !== "number" || !Number.isFinite(qty) || !(qty > 0) ||
+      Math.round(qty * 1000) !== qty * 1000 || qty > batch.qty)
+    throw new AppError("invalid_qty");
+  if (to === batch.location) return batch;
+  if (qty === batch.qty) {
+    batch.location = to;
+    return batch;
+  }
+  const moved = { ...batch, id: store.nextId("batch"), qty, location: to };
+  batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
+  store.data.batches.push(moved);
+  const ref = `transfer:${batch.id}:${moved.id}`;
+  record(store, { type: "adjust", batchId: batch.id, qty: -qty, at, ref });
+  record(store, { type: "adjust", batchId: moved.id, qty, at, ref });
+  return moved;
+}
